from pathlib import Path
import re
for f in sorted(Path('/docs').glob('*.txt')):
 lines=f.read_text().splitlines(); page='?'; hits=[]
 for i,l in enumerate(lines):
  if re.search(r'--- page (\\d+) ---',l): page=re.search(r'--- page (\\d+) ---',l).group(1)
  if re.search(r'governed|governing law|applicable law',l,re.I):
   hits.append((page,' '.join(lines[max(0,i-1):i+5])))
 print(f.name)
 for p,t in hits: print('PAGE',p,t)
 if not hits: print('NO MATCH; TAIL:', ' '.join(lines[-90:]))
