/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
import re
for f in sorted(Path('/docs').glob('*.txt')):
 s=f.read_text(); s=' '.join(s.split()); hits=list(re.finditer('California',s,re.I))
 if hits:
  print(f.name)
  for m in hits:
   page=re.findall(r'--- page (\\d+) ---',s[:m.start()]);print('p.'+(page[-1] if page else '?'),s[max(0,m.start()-100):m.end()+100])
print('OTHER CLAUSES')
for f in sorted(Path('/docs').glob('*.txt')):
 s=' '.join(f.read_text().split())
 for m in re.finditer(r'governed|choice of law|construction, interpretation',s,re.I):
  if 'California' not in s: print(f.name, s[m.start():m.start()+210])
